html:
{#- The showroom receipt (SP-102): a sale or a return of the showroom, printed by the cashier. -#}
{% extends "smart_power/templates/print/base_rtl.html" %}
{%- set listed = namespace(total=0) -%}
{%- for r in doc.items %}{% set listed.total = listed.total + (r.price_list_rate or 0) * (r.qty or 0) %}{% endfor -%}
{% block title %}
<style>.sp-receipt { max-width: 90mm; margin: 0 auto; } .sp-receipt td, .sp-receipt th { padding: 2px 4px; } .sp-receipt .sp-total td { font-weight: bold; border-top: 1px solid #000; }</style>
<div class="sp-receipt">
	<h3 style="text-align: center; margin-bottom: 4px">{{ doc.company }}</h3>
	<h4 style="text-align: center; margin-top: 0">{{ _("Showroom Return") if doc.is_return else _("Showroom Receipt") }}</h4>
	<div>{{ _("Receipt No.") }}: <span class="sp-num">{{ doc.name }}</span></div>
	{%- if doc.is_return %}<div>{{ _("Return of") }}: <span class="sp-num">{{ doc.return_against }}</span></div>{% endif %}
	<div>{{ _("Date") }}: {{ datetime_12h(doc.creation) }}</div>
	<div>{{ _("Customer") }}: {{ doc.customer_name }}</div>
	<div>{{ _("Cashier") }}: {{ frappe.db.get_value("User", doc.owner, "full_name") or doc.owner }}</div>
</div>
{% endblock %}
{% block body %}
<div class="sp-receipt">
<table class="sp-table">
	<thead><tr><th>{{ _("Item") }}</th><th>{{ _("Qty") }}</th><th>{{ _("Price") }}</th><th>{{ _("Amount") }}</th></tr></thead>
	<tbody>
	{%- for r in doc.items %}
		<tr>
			<td>{{ r.item_name }}{% if r.serial_no %}<div class="sp-serials">{{ _("Serial No") }}: {{ r.serial_no.replace("\n", "، ") }}</div>{% endif %}</td>
			<td class="sp-num">{{ frappe.format(r.qty|abs, "Float") }}</td>
			<td class="sp-num">{{ money(r.rate, doc.currency) }}</td>
			<td class="sp-num">{{ money(r.amount|abs, doc.currency) }}</td>
		</tr>
	{%- endfor %}
	</tbody>
</table>
<table style="width: 100%">
	{%- set given = (listed.total|abs) - (doc.grand_total|abs) %}
	{%- if given > 0.005 %}
	<tr><td>{{ _("Before discount") }}</td><td class="sp-num">{{ money(listed.total|abs, doc.currency) }}</td></tr>
	<tr><td>{{ _("Discount") }}</td><td class="sp-num">{{ money(given, doc.currency) }}</td></tr>
	{%- endif %}
	<tr class="sp-total"><td>{{ _("Refunded") if doc.is_return else _("Total") }}</td><td class="sp-num">{{ money(doc.grand_total|abs, doc.currency) }}</td></tr>
	{%- for p in doc.payments if p.amount %}
	<tr><td>{{ _(p.mode_of_payment) }}</td><td class="sp-num">{{ money(p.amount|abs, doc.currency) }}</td></tr>
	{%- endfor %}
</table>
<div style="margin-top: 6px">{{ ar_words(doc.grand_total) }}</div>
<div style="text-align: center; margin-top: 10px">{{ _("Thank you for buying from Smart Power") }}</div>
</div>
{% endblock %}
